<script setup lang="ts">
import {computed} from 'vue'
import type {FieldDefinition,FieldValue} from '../types'
const props=defineProps<{definitions:FieldDefinition[];fields:Record<string,FieldValue>;readonlyKeys?:string[]}>()
const emit=defineEmits<{change:[key:string,value:string,type:string];reference:[field:FieldDefinition,referenceKey:string,optionValue?:string]}>()
const selectItems=(field:FieldDefinition)=>[{label:'Не указано',value:'__empty'},...(field.options||[]).filter(o=>!o.hidden||o.value===props.fields[field.key]?.value).sort((a,b)=>Number(Boolean(a.referenceKey))-Number(Boolean(b.referenceKey))).map(o=>({...o,label:o.inputLabel||o.label}))]
function select(field:FieldDefinition,value:string){const option=field.options?.find(o=>o.value===value);if(option?.referenceKey)emit('reference',field,option.referenceKey,value);else{for(const key of new Set(field.options?.map(o=>o.referenceKey).filter(Boolean)))emit('change',key!,'','textarea_users');emit('change',field.key,value==='__empty'?'':value,'select')}}
const referenceText=(field:FieldDefinition)=>{const option=field.options?.find(o=>o.value===props.fields[field.key]?.value);return option?.referenceKey?props.fields[option.referenceKey]?.value:''}
const checkboxOption=(field:FieldDefinition)=>field.options?.find(o=>o.value===props.fields[field.key]?.value)||field.options?.find(o=>!o.hidden)
const groups=computed(()=>{const result:{name:string;fields:FieldDefinition[]}[]=[];for(const field of props.definitions){if(field.valueType==='checkbox'&&!field.options?.some(o=>!o.hidden)&&!props.fields[field.key]?.value)continue;const name=field.group||'Параметры исследования';let group=result.at(-1);if(!group||group.name!==name){group={name,fields:[]};result.push(group)}group.fields.push(field)}return result})
</script>
<template><section v-for="(group,index) in groups" :key="index" class="structured-group"><h3 v-if="groups.length>1" class="mb-5">{{group.name}}</h3><div class="grid grid-cols-1 md:grid-cols-2 gap-6">
  <UFormField v-for="field in group.fields" :key="field.key" :data-field="field.key" :label="field.valueType==='checkbox'&&field.options?.length?undefined:field.label">
    <template v-if="field.referenceKey"><UButton color="neutral" variant="outline" icon="i-lucide-book-open" @click="emit('reference',field,field.referenceKey)">Выбрать из справочника</UButton><p v-if="fields[field.key]?.value" class="preserve-lines mt-3">{{fields[field.key].value}}</p><UButton v-if="fields[field.key]?.value" color="neutral" variant="ghost" size="sm" @click="emit('change',field.key,'',field.valueType||'string')">Очистить</UButton></template>
    <template v-else-if="field.valueType==='select'&&field.options?.length"><USelect :model-value="fields[field.key]?.value||'__empty'" :items="selectItems(field)" @update:model-value="select(field,$event)" class="w-full"/><template v-if="referenceText(field)"><p class="preserve-lines mt-3">{{referenceText(field)}}</p><UButton color="neutral" variant="ghost" size="sm" icon="i-lucide-book-open" @click="emit('reference',field,field.options!.find(o=>o.value===fields[field.key]?.value)!.referenceKey!,fields[field.key]?.value)">Изменить выбор</UButton></template></template>
    <UCheckbox v-else-if="field.valueType==='checkbox'&&field.options?.length" :model-value="Boolean(fields[field.key]?.value&&fields[field.key]?.value!=='0')" :label="checkboxOption(field)?.label||field.label" @update:model-value="emit('change',field.key,$event?checkboxOption(field)?.value||'':'','checkbox')" class="min-h-11 items-center"/>
    <UTextarea v-else-if="field.kind==='get'||field.kind.includes('TextArea')" :model-value="fields[field.key]?.value||''" @update:model-value="emit('change',field.key,$event,field.valueType||'string')" :rows="3" autoresize class="w-full"/>
    <UInput v-else :model-value="fields[field.key]?.value||''" @update:model-value="emit('change',field.key,$event,field.valueType||'string')" :readonly="readonlyKeys?.includes(field.key)" class="w-full"/>
  </UFormField>
</div></section></template>
